# ---------------------------------------------------------------- 8. Speed (H3)
def speed(l):
    out = collections.defaultdict(list)
    for r in sorted((r for r in read_csv("speed_medians.csv") if r["session"] == l), key=lambda r: int(r["rep"])): out[r["condition"]].append(float(r["tok_s_total_median_of_7"]))
    return dict(out)
SP = {l: speed(l) for l in SESS}; OUT["speed_raw"] = SP
assert all(len(v) == 3 for l in SESS for v in SP[l].values()) and all(len(SP[l]) == 4 for l in SESS), "speed inputs: expected 4 conditions x 3 repetitions per session"
def pooled_ratio(xs, ys): return float(np.median(ys) / np.median(xs))
def ratio_ci_pooled(xs, ys, nb=NB):   # D2 construction: resample the pooled medians within arm
    rng = np.random.default_rng(1); x = np.array(xs); y = np.array(ys)
    r = np.median(y[rng.integers(0, len(y), (nb, len(y)))], axis=1) / np.median(x[rng.integers(0, len(x), (nb, len(x)))], axis=1); return [float(np.percentile(r, 5)), float(np.percentile(r, 95))]
def ratio_ci_within(xsess, ysess, nb=NB):   # sensitivity: resample the 3 medians within each session, then pool
    rng = np.random.default_rng(1)
    def draw(sess):
        parts = [np.array(v)[rng.integers(0, len(v), (nb, len(v)))] for v in sess]; return np.median(np.concatenate(parts, axis=1), axis=1)
    r = draw(ysess) / draw(xsess); return [float(np.percentile(r, 5)), float(np.percentile(r, 95))]
OUT["H3"] = {}
md("### Layer 6 decode speed (H3). tok/s total, the three decode medians per session and condition (D2); each median is the median of 7 repetitions")
md("| condition | " + " | ".join(SESS) + " |"); md("|---|" + "---|" * len(SESS))
for cond in ("prose_1", "prose_5", "code_1", "code_5"): md(f"| {cond} | " + " | ".join(", ".join(f"{v:.1f}" for v in SP[l][cond]) for l in SESS) + " |")
md(); md("Direction: **B is slower than A on prose and faster than A on code** in these isolated decode benchmarks. The ratios are of arm medians (B/A); a ratio above 1 means B is faster. The code ratio of about 1.4 comes from one fixed benchmark prompt (one prompt per condition); why the stock arm decodes that prompt more slowly was not investigated (a difference in speculative-draft acceptance on that prompt is one candidate, unverified). In the mixed 4-stream harness workload (table below) per-request tok/s differs by only a few percent between arms, so the isolated code advantage should not be read as a general speed gain, and the prose slowdown should not be read as general either. All H3 intervals are narrow because the three medians within a session are nearly identical (session-to-session spread is not captured, see sensitivity).")
md(); md("| condition | B/A, D2 interval [90% CI] | equivalent within [0.95, 1.05]? | B/A, within-session resampling [90% CI] | B/A clean-only A [90% CI] | session-specific B1/A1, B1/A2, B2/A1, B2/A2 | C/A |"); md("|---|---|---|---|---|---|---|")
for cond in ("prose_1", "prose_5", "code_1", "code_5"):
    A_all = SP["A1"][cond] + SP["A2"][cond]; B_all = SP["B1"][cond] + SP["B2"][cond]; C_all = SP["C1"][cond]
    A_clean = SP["A1"][cond][1:] + SP["A2"][cond]       # drops A1's first decode median (bench_streams full run, in which the A1 speed-step contaminated poll falls)
    rb = pooled_ratio(A_all, B_all); cb = ratio_ci_pooled(A_all, B_all); cw = ratio_ci_within([SP["A1"][cond], SP["A2"][cond]], [SP["B1"][cond], SP["B2"][cond]])
    rcl = pooled_ratio(A_clean, B_all); ccl = ratio_ci_pooled(A_clean, B_all)
    sess = [float(np.median(SP[b][cond]) / np.median(SP[a][cond])) for b in ("B1", "B2") for a in ("A1", "A2")]
    rc = pooled_ratio(A_all, C_all); eq = cb[0] >= 0.95 and cb[1] <= 1.05
    OUT["H3"][cond] = {"B_over_A": rb, "ci90_D2": cb, "ci90_within_session": cw, "B_over_A_clean_A": rcl, "ci90_clean": ccl, "session_ratios": sess, "equivalent": eq, "C_over_A": rc}
    md(f"| {cond} | {rb:.3f} [{cb[0]:.3f}, {cb[1]:.3f}] | {'yes' if eq else 'NO'} | [{cw[0]:.3f}, {cw[1]:.3f}] | {rcl:.3f} [{ccl[0]:.3f}, {ccl[1]:.3f}] | " + ", ".join(f"{v:.3f}" for v in sess) + f" | {rc:.3f} |")
md(); md("The D2 statement that this interval mostly shows session-to-session spread is **not supported**: the six values per arm are three batch medians within each of two sessions, so the interval reflects within-session repetition; two sessions per arm cannot characterise restart variability. The pooling of dependent observations is a limitation of the pre-registered construction. The clean-only column drops A1's first decode median (taken during the full benchmark run in which the A1 speed-step contaminated poll occurred, see D8 section) and is a sensitivity under the applied speed-step rule, not a demonstrated implementation of the original zero-contamination rule.")
md()
pf = {l: [(f"{int(r['prompt_tokens']):,}", int(r["tok_s"]), int(r["cached_tokens"])) for r in sorted((r for r in read_csv("prefill.csv") if r["session"] == l), key=lambda r: int(r["row"]))] for l in SESS}; OUT["prefill"] = pf
md("### Prefill tok/s from the full run (one run per session, exploratory; cached-token count in brackets)"); md("| ~prompt tokens | " + " | ".join(SESS) + " |"); md("|---|" + "---|" * len(SESS))
for n in range(len(pf["A1"])): md(f"| {pf['A1'][n][0]} | " + " | ".join(f"{pf[l][n][1]} ({pf[l][n][2]})" for l in SESS) + " |")
