for r in read_csv("request_stats.csv"): RQ[(r["session"], r["set"])].append({"tps": float(r["decode_tok_s"]), "accept": float(r["mtp_acceptance"])})
md("### Per-request decode tok/s and MTP draft acceptance, mean over first-attempt replies (exploratory, 4 concurrent streams)"); md("| set | " + " | ".join(f"{l} tok/s / accept" for l in SESS) + " |"); md("|---|" + "---|" * len(SESS))
