    keep = [k for k in cp.CAP if k not in excl]; r = contrast(ARM["A"], ARM["B"], sets=keep); tot = sum(len(ids_for(k, SESS[:4])) for k in cp.CAP)
    r["excluded"] = excl; r["retained_items"] = sum(r["n_items"].values()); r["total_items"] = tot; OUT["d8_sensitivity"][nm] = r
    fmt_contrast(f"D8 sensitivity (b) {nm}: B vs A on {len(keep)} benchmarks (excluded {excl or 'none'}; retained {r['retained_items']} of {tot} items; composite weights change from 1/6 to 1/{len(keep)} per benchmark)", r, sets=keep)
    cc = r["composite"]; md(f"Reading: negative direction {'persists' if cc['d'] < 0 else 'does not persist'}; the interval {'still lies below' if cc['ci95'][1] < -0.015 else 'crosses'} -1.5 pp. This is a different composite from the pre-registered six-benchmark one and does not reproduce the margin failure unless the whole interval lies below -1.5 pp."); md()
